using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using UnityEngine;
using UnityEngine.Rendering;

[DefaultExecutionOrder(-60)] public sealed class SurfaceScatter:MonoBehaviour {
 [StructLayout(LayoutKind.Sequential)]struct Rock{public double x,y,z,radius;}
 [DllImport("blackhole",CallingConvention=CallingConvention.Cdecl)]static extern int bh_set_rocks([In]Rock[] rocks,int count);
 public static SurfaceScatter Current;PlanetExpedition expedition;PlanetExpedition.Planet planet;Camera view;Mesh mesh,combinedMesh;GameObject field;Material material;readonly List<Vector3> positions=new List<Vector3>();readonly List<float> radii=new List<float>();Rock[] native=new Rock[192];Matrix4x4[] matrices=new Matrix4x4[192];string cell="";
 public int Count{get{return positions.Count;}}public int RenderedVertices{get{return combinedMesh!=null?combinedMesh.vertexCount:0;}}
 public void Initialize(PlanetExpedition owner){Current=this;expedition=owner;view=Camera.main;var source=GameObject.CreatePrimitive(PrimitiveType.Sphere);mesh=Instantiate(source.GetComponent<MeshFilter>().sharedMesh);Destroy(source);var verts=mesh.vertices;for(int i=0;i<verts.Length;i++){Vector3 d=verts[i].normalized;float noise=Mathf.Sin(d.x*17+d.y*11)*Mathf.Cos(d.z*13+d.y*7);verts[i]=d*(.92f+.08f*noise);}mesh.vertices=verts;mesh.RecalculateNormals();mesh.RecalculateBounds();material=new Material(Shader.Find("Universal Render Pipeline/Lit"));material.SetColor("_BaseColor",new Color(.65f,.65f,.65f));material.SetTexture("_BaseMap",Resources.Load<Texture2D>("Surfaces/rock_diff"));material.SetFloat("_Metallic",.05f);material.SetFloat("_Smoothness",.15f);material.enableInstancing=false;}
 public float Altitude(Vector3 p,float alt){if(planet==null||alt>15)return alt;Vector3 local=p-planet.body.P;for(int i=0;i<positions.Count;i++){Vector3 d=local-positions[i];if(d.sqrMagnitude<100)alt=Mathf.Min(alt,d.magnitude-radii[i]*.94f);}return alt;}
 public Vector3 Clearance(Vector3 p,float clearance){if(planet==null)return p;for(int i=0;i<positions.Count;i++){Vector3 c=planet.body.P+positions[i],d=p-c;float r=radii[i]+clearance;if(d.sqrMagnitude<r*r&&d.sqrMagnitude>.001f)p=c+d.normalized*r;}return p;}
 void Rebuild(Vector3 dir){positions.Clear();radii.Clear();Vector3[] normals={Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};for(int face=0;face<6;face++){Vector3 n=normals[face];float facing=Vector3.Dot(dir,n);if(facing<.55f)continue;Vector3 a=new Vector3(n.y,n.z,n.x),b=Vector3.Cross(n,a),cube=dir/facing;float tile=30/(float)planet.body.radius;int cx=Mathf.FloorToInt((Vector3.Dot(cube,a)+1)/tile),cy=Mathf.FloorToInt((Vector3.Dot(cube,b)+1)/tile);
  for(int x=cx-3;x<=cx+3;x++)for(int y=cy-3;y<=cy+3;y++){int seed=unchecked(x*73856093^y*19349663^face*83492791^(int)planet.body.seed*1107);var rng=new System.Random(seed);if(rng.NextDouble()<.3)continue;float u=(x+(float)rng.NextDouble())*tile-1,v=(y+(float)rng.NextDouble())*tile-1;if(Mathf.Abs(u)>1||Mathf.Abs(v)>1)continue;Vector3 d=PlanetTerrainLOD.Direction(face,u,v);float h=PlanetExpedition.Height(d,planet.body.seed,planet.body.radius);if(h<1)continue;float r=.8f+(float)rng.NextDouble()*3.6f;positions.Add(d*((float)planet.body.radius+h+r*.35f));radii.Add(r);if(positions.Count>=190){BuildVisible();return;}}}BuildVisible();
 }
 void BuildVisible(){if(field==null){field=new GameObject("Deterministic local boulder field");field.AddComponent<MeshFilter>();field.AddComponent<MeshRenderer>();}field.transform.SetParent(planet.root.transform,false);field.transform.localPosition=Vector3.zero;field.transform.localRotation=Quaternion.identity;field.transform.localScale=Vector3.one;if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Lit"));material.SetColor("_BaseColor",new Color(.65f,.65f,.65f));material.SetTexture("_BaseMap",Resources.Load<Texture2D>("Surfaces/rock_diff"));material.SetFloat("_Metallic",.05f);material.SetFloat("_Smoothness",.15f);}if(combinedMesh!=null)Destroy(combinedMesh);combinedMesh=new Mesh{name="Boulder geometry / matching local native field",indexFormat=IndexFormat.UInt32};var pieces=new CombineInstance[positions.Count];for(int i=0;i<pieces.Length;i++)pieces[i]=new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(positions[i],Quaternion.Euler(0,i*137,0),Vector3.one*radii[i])};if(pieces.Length>0)combinedMesh.CombineMeshes(pieces,true,true);combinedMesh.RecalculateBounds();field.GetComponent<MeshFilter>().sharedMesh=combinedMesh;field.GetComponent<Renderer>().sharedMaterial=material;field.SetActive(pieces.Length>0);}
 void Update(){if(expedition==null)return;Vector3 p=view.transform.position;var nearest=expedition.Nearest(p);if(nearest==null||expedition.Alt(p)>200){positions.Clear();if(field!=null)field.SetActive(false);planet=null;cell="";bh_set_rocks(native,0);return;}Vector3 dir=(p-nearest.body.P).normalized;string next=nearest.key+"/"+Mathf.FloorToInt(dir.x*(float)nearest.body.radius/15)+"/"+Mathf.FloorToInt(dir.y*(float)nearest.body.radius/15)+"/"+Mathf.FloorToInt(dir.z*(float)nearest.body.radius/15);if(next!=cell){planet=nearest;cell=next;Rebuild(dir);}for(int i=0;i<positions.Count;i++){Vector3 c=planet.body.P+positions[i];native[i]=new Rock{x=c.x,y=c.y,z=c.z,radius=radii[i]*.94};matrices[i]=Matrix4x4.TRS(c,Quaternion.Euler(0,i*137,0),Vector3.one*radii[i]);}bh_set_rocks(native,positions.Count);}
 void OnDestroy(){bh_set_rocks(native,0);if(mesh!=null)Destroy(mesh);if(combinedMesh!=null)Destroy(combinedMesh);if(field!=null)Destroy(field);if(material!=null)Destroy(material);if(Current==this)Current=null;}
}
